#!/usr/bin/env python3
from pathlib import Path
import base64,json,html
here=Path(__file__).resolve().parent;repo=here.parents[2]
font=base64.b64encode((repo/'apps/ios/CupSeason/Resources/Fonts/IBMPlexSansCondensed-Bold.ttf').read_bytes()).decode()
mono=base64.b64encode((repo/'apps/ios/CupSeason/Resources/Fonts/IBMPlexMono-Regular.ttf').read_bytes()).decode()
def shot(file,title,desc='',cls=''):
 return f'<figure class="{cls}"><button class="image-button" data-image="{file}" aria-label="Enlarge {html.escape(title)}"><img src="{file}" alt="{html.escape(title)}" loading="lazy"></button><figcaption><strong>{title}</strong><p>{desc}</p></figcaption></figure>'
styles='''
*{box-sizing:border-box}body{margin:0;background:#0F1A15;color:#F1F4EF;font:16px/1.5 system-ui,sans-serif}a{color:#F1F4EF;text-underline-offset:4px}button,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #5FA271;outline-offset:4px}main{max-width:1280px;margin:auto;padding:40px 28px 80px}.kicker,.tag,nav button,.number,select,dt{font-family:Mono,monospace;font-size:12px;letter-spacing:.05em}.kicker{color:#9BA69D;text-transform:uppercase}header{padding:20px 0 32px;border-bottom:1px solid #4A6155}h1{font:700 clamp(48px,7vw,86px)/.98 Board,sans-serif;margin:20px 0;max-width:900px;text-transform:uppercase}h2{font:700 36px/1.1 Board,sans-serif;margin:32px 0 12px}h3{font:700 24px Board,sans-serif;margin:24px 0 8px}p{max-width:760px;margin:8px 0;color:#9BA69D}.lead{font-size:19px;max-width:830px}.tag{display:inline-block;padding:6px 10px;background:#26352E;color:#F1F4EF;margin:20px 10px 0 0}nav{display:flex;gap:28px;border-bottom:1px solid #4A6155;margin-bottom:28px;overflow:auto}nav button{border:0;background:none;color:#9BA69D;white-space:nowrap;min-height:64px;padding:18px 0;border-bottom:3px solid transparent}nav button[aria-selected=true]{color:#F1F4EF;border-bottom-color:#F1F4EF}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;margin:24px 0 42px}.pair{grid-template-columns:repeat(2,minmax(0,1fr));max-width:820px}.store{grid-template-columns:repeat(4,minmax(0,1fr))}.artifact{grid-template-columns:repeat(2,minmax(0,1fr));max-width:900px}figure{margin:0;min-width:0}figcaption{margin-top:12px}figcaption strong{font:700 20px Board,sans-serif}figcaption p{font-size:14px}.image-button{display:block;border:0;padding:0;width:100%;background:transparent;text-align:left}.image-button img{display:block;width:100%;height:auto;border:1px solid #4A6155}.controls{display:flex;flex-wrap:wrap;gap:14px;margin:28px 0}.controls label{display:flex;gap:8px;align-items:center;color:#9BA69D}.controls select{min-height:44px;background:#26352E;color:#F1F4EF;border:0;border-radius:10px;padding:10px}.note{padding:16px 0;border-top:1px solid #4A6155;border-bottom:1px solid #4A6155;margin:24px 0}.note strong{color:#F1F4EF}details{margin:32px 0}summary{cursor:pointer;min-height:44px;padding:10px 0}footer{border-top:1px solid #4A6155;margin-top:50px;padding-top:24px;font-size:14px}dialog{border:1px solid #4A6155;background:#0F1A15;color:#F1F4EF;max-width:min(1120px,96vw);max-height:94vh;padding:20px}dialog::backdrop{background:rgb(0 0 0 / .88)}dialog img{display:block;max-width:100%;height:auto;margin-top:16px}dialog button{background:#5FA271;color:#0F1A15;border:0;padding:10px 20px;border-radius:10px;position:sticky;top:0;z-index:1;min-height:44px}code{overflow-wrap:anywhere}li{color:#9BA69D;margin-bottom:10px}li strong{color:#F1F4EF}[hidden]{display:none!important}@media(max-width:760px){main{padding:20px 18px 50px}.grid,.store{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.pair,.artifact{grid-template-columns:1fr}nav{gap:18px}.controls{display:grid}h1{font-size:52px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
'''
body='''<header><div class="kicker">Cup Season · September 25, 2026 · Local review</div><h1>Three things<br>for the morning.</h1><p class="lead">The Play journey, a round worth sharing, and an eight-image App Store sequence. Built on the verified audit integration, using the current design system.</p><span class="tag">Setup + share UI checks passed</span><span class="tag">Preflight: 0 failures / 0 warnings</span><p>All people and records shown are review fixtures. Nothing in this package has been deployed or uploaded.</p></header>
<nav role="tablist" aria-label="Review packages"><button id="tab-play" role="tab" aria-controls="play" aria-selected="true" data-tab="play">01 / Play</button><button id="tab-share" role="tab" aria-controls="share" aria-selected="false" data-tab="share">02 / Sharing</button><button id="tab-store" role="tab" aria-controls="store" aria-selected="false" data-tab="store">03 / App Store</button></nav>
<section id="play" role="tabpanel" aria-labelledby="tab-play"><h2>From setup to the record.</h2><p>Tee off stays in reach. Course entry comes before offline preparation. Teams stack when names need room, and the keyboard has a Close control. The live scoring and receipt mechanics remain the verified audit implementation.</p><div class="controls"><label>Phone <select id="phone"><option value="standard">Standard iPhone</option><option value="small">Small iPhone SE</option></select></label><label>Printing <select id="theme"><option value="dark">Dark</option><option value="light">Light</option></select></label><label>Text <select id="size"><option value="large">Standard</option><option value="AX3">Accessibility 3</option></select></label></div><p id="printing-note" hidden>Accessibility captures use the dark printing.</p><div class="grid" id="native-grid"></div><h3>The setup change</h3><div class="grid pair">'''
body+=shot('captures/before-setup-dark.png','Before','Offline preparation precedes the course; Tee off is below the form.')+shot('captures/standard-setup-dark-large.png','Review candidate','Course first, with the primary action anchored below the scroll.')
body+='</div><h3>When the connection drops</h3><div class="grid pair">'+shot('captures/standard-offline-dark-large.png','The live card','The existing status explicitly says the round is waiting to sync.')+shot('captures/keyboard.png','Rating keyboard','The keyboard can close without leaving setup. Captured in the UI test.')+'</div></section>'
body+='''<section id="share" role="tabpanel" aria-labelledby="tab-share" hidden><h2>One round record, wherever it goes.</h2><p>The course, date, gross and golfer now lead the recipient page in the same order as the exported card. The photo stays a clear plate. Its opt-out remains visible above the preview; the included message is available on demand.</p><div class="grid">'''
body+=shot('captures/standard-receipt-light-large.png','1. The receipt','The existing receipt remains the source for the accepted round.')+shot('captures/standard-share-photo-dark-large.png','2. The preview','Photo choice first. Sharing still sends the card and link through the audited flow.')+shot('captures/public-mobile-dark.png','3. The recipient','A readable record and one ordinary green action.')
body+='</div><h3>The public page, before and after</h3><div class="grid pair">'+shot('captures/before-public-mobile.png','Before','Gold frame, mixed typography and a separate visual language.')+shot('captures/public-mobile-light.png','Review candidate · light','The same token system, with warm paper for the light printing.')+'</div><h3>The exported cards</h3><p>The native card design is retained. These exports verify its composition with no photo, a photo and longer names. The abstract image below is a layout test, not a course photograph.</p><div class="grid artifact">'
for file,title in [('artifact-share.png','No photo'),('artifact-share-photo.png','With photo'),('artifact-share-long.png','Long course and golfer'),('artifact-share-long-photo.png','Long names with photo')]:body+=shot('captures/'+file,title)
body+='</div><details><summary>More recipient states</summary><div class="grid">'+shot('captures/public-small-long.png','320-pixel page','Long names and nine-hole label.')+shot('captures/public-no-band.png','No established band','The page makes no performance claim.')+shot('captures/public-photo-mobile.png','Photo included','Only loaded when the shared record permits it.')+'</div>'+shot('captures/public-desktop-dark.png','Desktop recipient')+'</details><p class="note"><strong>Verification:</strong> Photo inclusion, opt-out, opt-in and no-photo states pass. Native share cancellation closes the presentation cleanly. The recipient checks cover overflow, private-points suppression, missing photos and the generated pennant.</p></section>'
body+='''<section id="store" role="tabpanel" aria-labelledby="tab-store" hidden><h2>The product carries the story.</h2><p>Eight candidates at 1320 × 2868, built from actual 6.9-inch app captures. Each keeps the full app screen and adds one short headline. No abstract photo fixture appears in this sequence.</p><p><a href="store-sequence.png">Open the full contact sheet</a> · <a href="store-captions.md">Read captions and source notes</a></p><div class="grid store">'''
for row in json.loads((here/'store-captions.json').read_text()):body+=shot('store/'+row['file'],html.escape(row['headline'].replace('\n',' ')),html.escape(row['caption']))
body+='''</div><p class="note"><strong>For your decision:</strong> Review the order and captions before release. The PNGs meet Apple’s listed 6.9-inch dimensions; no App Store Connect submission was made.</p></section><footer><p>Branch: <code>codex/play-share-store-review-2026-09-25</code></p><p><a href="handoff.md">Implementation and verification handoff</a> · <a href="design-direction.md">Design direction</a> · <a href="https://developer.apple.com/help/app-store-connect/reference/app-information/screenshot-specifications">Apple screenshot specifications</a></p></footer><dialog id="zoom"><button id="close-zoom">Close</button><img id="zoom-image" alt=""></dialog>'''
script='''
const tabs=[...document.querySelectorAll('[data-tab]')];function selectTab(button){for(const t of tabs){const selected=t===button;t.setAttribute('aria-selected',selected);t.tabIndex=selected?0:-1;document.getElementById(t.dataset.tab).hidden=!selected}}for(const t of tabs)t.addEventListener('click',()=>selectTab(t));document.querySelector('nav').addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();let i=tabs.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();selectTab(tabs[i])});selectTab(tabs[0]);
const zoom=document.getElementById('zoom');document.addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(!b)return;document.getElementById('zoom-image').src=b.dataset.image;document.getElementById('zoom-image').alt=b.getAttribute('aria-label').replace('Enlarge ','');zoom.showModal()});document.getElementById('close-zoom').onclick=()=>zoom.close();
function nativeGrid(){const phone=document.getElementById('phone').value,size=document.getElementById('size').value;const theme=size==='AX3'?'dark':document.getElementById('theme').value;document.getElementById('theme').disabled=size==='AX3';document.getElementById('printing-note').hidden=size!=='AX3';document.getElementById('native-grid').innerHTML=['setup','live','receipt'].map((s,i)=>`<figure><button class="image-button" data-image="captures/${phone}-${s}-${theme}-${size}.png" aria-label="Enlarge ${s}"><img src="captures/${phone}-${s}-${theme}-${size}.png" alt="${s}: ${phone}, ${theme}, ${size}"></button><figcaption><strong>${['Set up the round','Score it live','The finished record'][i]}</strong></figcaption></figure>`).join('')}for(const id of ['phone','theme','size'])document.getElementById(id).addEventListener('change',nativeGrid);nativeGrid();
'''
(here/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cup Season · Morning Review</title><style>@font-face{font-family:Board;src:url(data:font/ttf;base64,'+font+')}@font-face{font-family:Mono;src:url(data:font/ttf;base64,'+mono+')}'+styles+'</style><main>'+body+'</main><script>'+script+'</script></html>')
print('Review gallery built.')
